import{_ as t}from"./chunks/a7b3a30358c086b3a39e.CS8YSe9M.js";import{_ as r}from"./chunks/ac945418977052fbacd6.CObdY42w.js";import{_ as i}from"./chunks/a01c60186d5c886ee5b6.Bzujk2Pa.js";import{_ as o}from"./chunks/9d7754e433cb81649464.Chh4eyeD.js";import{_ as l,C as n,o as h,c as s,j as a,a as d,E as c,a6 as m}from"./chunks/framework.CnPv4DE1.js";const A=JSON.parse('{"title":"生活就是一场电子游戏（你无法逃脱矩阵）","description":"","frontmatter":{"title":"生活就是一场电子游戏（你无法逃脱矩阵）","originalTitle":"Life Is A Video Game (You Can’t Escape The Matrix)","date":"2023-08-26","originalUrl":"https://thedankoe.com/letters/life-is-a-video-game-you-cant-escape-the-matrix/","minutes":15,"sourceHash":"22086ce88d0f2f1ddaab0c8a815c5b44fde769bcc6016788d62e0db22592dfd3","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/life-is-a-video-game-you-cant-escape-the-matrix/"}]]},"headers":[],"relativePath":"letters/life-is-a-video-game-you-cant-escape-the-matrix.md","filePath":"letters/life-is-a-video-game-you-cant-escape-the-matrix.md"}'),u={name:"letters/life-is-a-video-game-you-cant-escape-the-matrix.md"};function f(b,p,q,k,_,x){const e=n("ArticleMeta");return h(),s("div",null,[p[0]||(p[0]=a("h1",{id:"生活就是一场电子游戏-你无法逃脱矩阵",tabindex:"-1"},[d("生活就是一场电子游戏（你无法逃脱矩阵） "),a("a",{class:"header-anchor",href:"#生活就是一场电子游戏-你无法逃脱矩阵","aria-label":'Permalink to "生活就是一场电子游戏（你无法逃脱矩阵）"'},"​")],-1)),c(e),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/ZcegvPYE2MI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我记得早上3点就爬起来，只为了在去上高中前能玩会儿游戏。</p><p>从《光环3》（Halo 3）和《使命召唤》（Call Of Duty），到《魔兽世界》（World Of Warcraft）和《英雄联盟》（League Of Legends）。</p><p>毫不夸张地说，我当时彻底上瘾了。</p><p>在电子游戏中提升等级，比在现实中提升等级更重要。</p><p>但我什么都不想改变。</p><p>不然我怎么写得出这期邮件通讯呢？</p><p>心理学、形而上学、自我提升以及现代商业，全都指向了同一点：生活就是一场电子游戏。</p><p>当然，这是比喻意义上的。我并不是说宇宙的底层架构是外星人在人类出现之前建造的一台超级计算机……但正如我们将要学到的，它们非常相似（而且我对这个想法也并不完全排斥。谁<em>真的</em>知道呢？）。</p><p>我想逐一拆解每个视角，以便你能：</p><ul><li>朝着你的目标取得进展（并爱上这个过程）</li><li>理解如何进入最佳意识状态</li><li>别再把生活看得那么严肃，去创造你理想的未来</li><li>重塑你自己，或者重塑玩这场生活游戏的那个角色</li><li>利用你的角色作为杠杆（Leverage），去追求你一生的事业，并赚取有意义的收入</li></ul><p>游戏是结构化的信息流。</p><p>生活就是处于形成之中的信息（in-formation），而我们的生活质量取决于我们处理它的能力。</p><p>当我们远远超出了自己的边界，过度深入未知领域时，就会产生太多的刺激。我们无法代谢这些体验。信息堆积起来，造成了焦虑和不知所措。</p><p>当我们远远退缩于自己的边界之内，过度沉浸在已知领域时，生活中就几乎没有让它值得一过的新奇感了。我们的心智得不到刺激。信息太容易消化，我们就会感到无聊。</p><p>意识每秒能处理50比特的信息。</p><p>潜意识每秒能处理1100万比特的信息。</p><p>随着我们处理信息（或玩游戏）的效率越来越高，我们的潜意识力量也会随之增强，从而释放出意识层面的注意力，去投入到我们认为有意义的事情上。</p><p>在电子游戏中，你拥有一张地图。觉察之光会照亮你去过的地方和你经历过的事情。这些知识让你能在未来做出更好的决定。</p><p>地图上的黑暗区域就是未知，而你不会让自己一下子冲得离已知区域太远。</p><p>你必须慢慢刺透未知，通过获取技能和管理情绪让体验常态化，然后再继续向前推进。</p><p>生命的意义在于提升你的意识。</p><p>只有生活在你的边界上，这才是可能的。去拥抱人生的故事。高潮、低谷、成功，以及灾难性的失败。你能呆的最悲惨的地方就是停滞在中间。</p><h2 id="心理学-电子游戏如何让你对进步上瘾" tabindex="-1">心理学：电子游戏如何让你对进步上瘾 <a class="header-anchor" href="#心理学-电子游戏如何让你对进步上瘾" aria-label="Permalink to &quot;心理学：电子游戏如何让你对进步上瘾&quot;">​</a></h2><blockquote><p>最优的内心体验状态是一种意识中有秩序的状态。当精神能量（即注意力）投入到现实目标中，并且技能与行动机会相匹配时，这种状态就会发生。对目标的追求能给觉察带来秩序，因为人必须将注意力集中在手头的任务上，并暂时忘记其他一切。 —— 米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>心流（Flow）。</p><p>你以前肯定听说过它。</p><p>这是所有古人、神秘主义者和心理学家的教义所共同指向的最佳意识状态。</p><p>在这里，你与“做”或“存在”融为一体。</p><p>你放下了自我意识，在生活中穿行，心中没有一丝世俗的担忧。</p><p>看来，美好生活的关键在于将注意力投入到我们认为有意义的事情上。但你认为有意义的事情，是通过将注意力投入到你剔除为无意义的事情中才发现的。这个试错、起伏、专注与分心的过程，正是让生活保持乐趣的自然平衡。</p><p>但如果你被困在低谷中，混乱就会随之而来。</p><h3 id="精神熵" tabindex="-1">精神熵 <a class="header-anchor" href="#精神熵" aria-label="Permalink to &quot;精神熵&quot;">​</a></h3><p>有序的意识创造了不同程度的心流状态。</p><p>“让意识变得有序”就是将你的注意力集中在外部或内部的事物上。外部的一项任务、一个情境或一场对话；或者是内部的一个想法、一种情绪或一种感觉。</p><p>两者都有各自的好处，并能改变我们大脑的运作方式。</p><p><img src="'+t+'" alt=""></p><p>当我们因分心而失去焦点时，我们就会增加熵增的概率——即衰退陷入混乱。精神熵是指心智倾向于一种无序的意识状态。</p><p>当我们赋予一个负面想法生命或注意力时，它就会成倍增加。</p><p>社交媒体上一篇关于吃鸡蛋会致癌的帖子，会让你联想到奶奶的健康、你的饮食选择、你是否发挥了自己的潜力、食物如何影响你的皮肤质量、你下一顿要吃什么，等等。</p><p>当我们运用人类特有的拉开距离、获取更广阔视角的能力，并将注意力重新集中在一个能带来成长的方向上去“做”或“存在”时，我们就能逆转熵。</p><h3 id="电子游戏让意识变得有序" tabindex="-1">电子游戏让意识变得有序 <a class="header-anchor" href="#电子游戏让意识变得有序" aria-label="Permalink to &quot;电子游戏让意识变得有序&quot;">​</a></h3><p>通过解构电子游戏如何让意识变得有序，我们可以学到许多实用的经验。</p><p>这些经验可以用来增强我们的学习能力、技能获取和自信心。</p><p>当你刚开始玩一个游戏时：</p><ol><li>你完全不知道自己在干什么。</li><li>你会过一遍新手教程，这样你就不会一下子暴露在所有的内容中。</li><li>你在第一级练习，直到这个级别变得无聊。</li><li>系统向你介绍更多的技能、特性和能力供你练习。</li><li>你不断渐进式超载你所接受的挑战，直到你决定不再玩这个游戏为止。</li></ol><p>如果我们想在意识中保持秩序，技能与挑战之间就必须相匹配。</p><p><img src="'+r+'" alt=""></p><p>如果挑战对你的技能来说太高，你就会焦虑。</p><p>如果挑战对你的技能来说太低，你就会无聊。</p><p>所以，你首先要学习游戏规则。</p><p>“游戏”代表了生活中的任何情境。特别是那些你缺乏自信且看不到自己获胜希望的情境。</p><p>然后，你要练习这个游戏的机制。</p><p>这里有一系列的步骤或任务，同步提供教育和练习。</p><p>当你接触任何新事物（或对目前的尝试感到厌倦）时，请记住这一点。</p><p>如果你面临巨大的挑战，你需要在自己当前的级别上进行学习和练习。</p><p>如果你对当前级别的挑战感到无聊，你就需要让自己接触下一级的教育，练习新技能，并在向人生的下一个阶段跃升时，享受多巴胺加倍的神经化学鸡尾酒。</p><h3 id="将自我认知作为指南针" tabindex="-1">将自我认知作为指南针 <a class="header-anchor" href="#将自我认知作为指南针" aria-label="Permalink to &quot;将自我认知作为指南针&quot;">​</a></h3><p>平衡技能与挑战是你必须练习的元游戏（metagame）。</p><p>当你感到无聊时，你的思绪就会开始飘忽，并想：“我本可以把时间花在更好的事情上。”</p><p>你开始滑向以自我为中心。此时你要把注意力重新集中，给当前的局面增加点挑战。</p><p>即使你从事的工作总是那些重复性的任务，你也可以通过<em>创造</em>一个更具挑战性的游戏来让它变得更有趣。</p><p>你可能觉得每天散步很无聊，但如果你加点规则呢？比如试试看散步时不要踩到人行道上的裂缝。</p><p>当你感到焦虑时，你的大脑会抓住你身上的负面因素不放。</p><p>“我不够好。”</p><p>“大家会怎么看我脸上的这个瑕疵。”</p><p>“我的生意绝不可能赚那么多钱。”</p><p>你开始滑向难堪的自我意识，并任由负面想法成倍滋生。</p><p>同样的，停下来，拉开距离看。重新聚焦。</p><p>这需要刻意的练习才能养成习惯。</p><h2 id="形而上学-我们生活在一个基于生存的模拟世界中" tabindex="-1">形而上学：我们生活在一个基于生存的模拟世界中 <a class="header-anchor" href="#形而上学-我们生活在一个基于生存的模拟世界中" aria-label="Permalink to &quot;形而上学：我们生活在一个基于生存的模拟世界中&quot;">​</a></h2><blockquote><p>如果你在电脑上玩电子游戏，比如《毁灭战士》（Doom）或《神秘海域》（Uncharted），你会看到有着3D物体的引人入胜的3D世界。然而，所有的信息完全是2D的，受限于屏幕上的像素数量。当你把目光从电脑移向周围的世界时，情况也是如此。它同样有像素，所有的信息都是2D的。 —— 唐纳德·霍夫曼（Donald Hoffman）</p></blockquote><p>唐纳德·霍夫曼是一位认知心理学家兼作家，其代表作是《反对现实的理由》（<em>The Case Against Reality</em>）。</p><p>在这本书（以及我狂听的各种<a href="https://youtu.be/dd6CQCbk2ro" target="_blank" rel="noreferrer">播客</a>）中，他主张人类的感知是一个“用户界面”，它掩盖了现实的真实本质，以便我们能够生存下去。</p><p>自然选择并不偏爱那些能看到现实本来面目的生物。</p><p>这与特伦斯·麦肯纳（Terrance McKenna）等致幻剂爱好者的观点不谋而合，他们认为语言<em>就是</em>虚拟现实。感知是一个封闭系统，而致幻剂能让你看到基于适应性的感知之外的世界。</p><h3 id="时空作为一种压缩算法" tabindex="-1">时空作为一种压缩算法 <a class="header-anchor" href="#时空作为一种压缩算法" aria-label="Permalink to &quot;时空作为一种压缩算法&quot;">​</a></h3><p>霍夫曼主张，空间和时间是一种可视化工具。</p><p>它们是我们这个用户界面的操作系统。</p><p>想象一下电脑桌面屏幕。</p><p>主观现实就像一个被编程好的屏幕，用来帮助我们看到我们需要看到的东西，从而去做我们需要做的事情。</p><p>每一个“物质”对象都像是屏幕上的一个图标。</p><p>它很漂亮。它具有属性和特质。我们应该“认真对待它们，但不要照字面意思完全当真”。</p><p>你可以在屏幕上四处点击，执行特定任务，从而得出想要的结果。</p><p>这些想要的结果就是“适应性回报”。这些回报就像电子游戏里的积分。通过试错，我们学会了如何赢，以及如何进化。通过赢，你的后代就能进入下一关。</p><p>在现实世界的模拟中，看到真相的生物都灭绝了。就像一只试图与玻璃瓶交配的蚂蚁，因为它的感知被扭曲了。</p><h3 id="移除界面" tabindex="-1">移除界面 <a class="header-anchor" href="#移除界面" aria-label="Permalink to &quot;移除界面&quot;">​</a></h3><p>每个人都认为自己看到了真相，但其实更像是大家都身处同一个电子游戏中，比如《侠盗猎车手》（Grand Theft Auto）。</p><p>当我们看着运行这些程序的电脑和主机时，它们被包装得很好。</p><p>我们并<em>没看到</em>传输信息以在屏幕上生成画面的电线和二极管。而且，就算我们看到了，也对我们的生存毫无帮助。我们无法理解它，也无法拿那一堆杂乱的电子元件去<em>做</em>任何事。</p><p>更进一步来说，我们看不到也无法理解运行这个游戏的代码。</p><p>我们可以在这个理论与不二论（non-duality）、无限意识（infinite consciousness）以及唯心论/理念论（mentalism / idealism）之间建立联系。</p><p>如果你（用诸如致幻剂或高阶冥想之类的工具）移除了你的界面，你最终会发疯。你的自我（ego）将会消散，你会以一种完全不同的方式“活”着并运作。你的肉体或化身（avatar）将停止玩这个游戏——而且你很可能会很快死去。</p><p>人们不会每周7天、每天24小时都处在致幻剂状态，这是有原因的。</p><p>我们还远未达到那个进化阶段，但谁知道未来会怎样呢。</p><p>就目前而言，明智的做法是扎根于形而上学，并站在更高的视角于“物理”世界中采取行动。</p><h3 id="心智作为容器" tabindex="-1">心智作为容器 <a class="header-anchor" href="#心智作为容器" aria-label="Permalink to &quot;心智作为容器&quot;">​</a></h3><p>人类的心智是一个容器，现实从中流过。</p><p>可以把它想象成一台投影仪。</p><p>投影仪发出的光就是意识。</p><p>胶片就是心智。</p><p>光线照在胶片上，投射出人类所拥有的体验光谱。它构架了我们的感知。</p><h2 id="自我提升-如何重塑你自己-你的角色" tabindex="-1">自我提升：如何重塑你自己（你的角色） <a class="header-anchor" href="#自我提升-如何重塑你自己-你的角色" aria-label="Permalink to &quot;自我提升：如何重塑你自己（你的角色）&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>生活是一场游戏。</p><p>努力攒金币吧。</p><p>获取技能。</p><p>积累经验。</p><p>解锁新关卡。</p><p>最终，达到拥有足够资源去随心所欲的境界。</p><p>当你的运作框架聚焦于将实现你未来的过程时，你的专注力将坚不可摧，你将生活在自己设计的世界中。</p><p>电子游戏和现实生活的区别在于虚拟风险和真实风险。</p><p>电子游戏和现实生活的相同之处在于学习、练习，以及成为多巴胺瘾君子。</p><p>电子游戏有新手教程、职业、任务和可供探索的未知。</p><p>现实生活有童年、职业道路、责任，以及你尚未察觉的潜能——但一旦被发现——就能彻底改变你思考、行动和工作的方式。</p><p>一旦你理解了游戏与生活之间所展现的模式的重要性，你就可以开始以一种有利于你理想未来的方式来纠正你的行为了。</p><h3 id="增加自我的复杂性" tabindex="-1">增加自我的复杂性 <a class="header-anchor" href="#增加自我的复杂性" aria-label="Permalink to &quot;增加自我的复杂性&quot;">​</a></h3><blockquote><p>任何问题都无法在制造它的同一意识水平上得到解决。——阿尔伯特·爱因斯坦 (Albert Einstein)</p></blockquote><p>要提升你的意识，你必须提升你的思想层级。</p><p>要提升你的思想层级，你必须打开你的视野。</p><p>要打开你的视野，你必须识别问题，接受挑战，获取技能，并吸收超越你过往身份所需的知识。</p><p>随着思想层级的每一次提升，你的身份也必须随之改变。</p><p>你在脑海中将其组织为“自我”的那些知识、技能、信念和经验，决定了你所能获得的机遇。</p><p>在第一级，你可以接触到略高于你层级的机遇。你能在意识中察觉到的机遇存在于一个光谱上。</p><p>随着你的升级，你可以接触到你层级之下的所有机遇，以及那些依然略高于你的机遇。</p><p>让自己分心，永远看不到自己的潜能，这是对你生命极大的辜负。</p><h3 id="创造你要玩的游戏" tabindex="-1">创造你要玩的游戏 <a class="header-anchor" href="#创造你要玩的游戏" aria-label="Permalink to &quot;创造你要玩的游戏&quot;">​</a></h3><p>如果游戏有一个期望的结果（获胜）、一条通向那里的路径（进度）以及需要采取的习惯性行动（优先级），那么我们就可以从生活中的任何情境里创造出游戏。</p><p>目标、过程和优先级的这个普遍原则，正是人类行为的底层框架。</p><p>如果你没有目标，你就没有愿景。</p><p>如果你没有路径，你就没有清晰度。</p><p>如果你没有任务，你就没有专注力。</p><p>你生活中的大部分问题，都可以通过理解和应用这个原则来解决。</p><p>要创造一个游戏，你需要一个界定你注意力的目标层级。</p><p>举个例子：</p><ul><li>一个十年目标（让你的愿景得以绽放）</li><li>年度目标</li><li>月度目标</li><li>每周目标</li></ul><p>所有这些都只需松散地留在你的脑海深处。它们不应成为你的主人，而应是你的向导。</p><p>只有以此为起点，你才能将你的学习和日常能够撬动杠杆的行动与它们对齐。</p><p>你所取得的进展会增加大脑中有意义的多巴胺，这种感觉棒极了。</p><p>如果你能把注意力锚定在这个目标层级上，你大部分的烦恼就会消失。</p><p>你过度关注生活中消极的一面，是因为你还没有建立起需要你投入注意力的积极责任。</p><p>你在目标上投入的注意力越多，它们的引力就越强。</p><h3 id="一切改变皆是行为改变" tabindex="-1">一切改变皆是行为改变 <a class="header-anchor" href="#一切改变皆是行为改变" aria-label="Permalink to &quot;一切改变皆是行为改变&quot;">​</a></h3><p>要改变你的生活，你必须改变你的行动。</p><p>要（朝着正确的方向）改变你的行动，你需要一个计划。别无他法。如果你不创造自己的计划，就会有人为你制定计划。</p><p>要坚持这个计划，你需要一个系统。</p><p>系统就是有组织的行为改变。</p><p>要创造一个系统，你必须攻克你的目标，拥抱试错的本质，在你的成功上加倍投入，并坚持不懈，直到“成功”成为你生活各个领域的默认状态。无论是健康、财富、人际关系还是幸福。</p><h2 id="商业-新的数字社会" tabindex="-1">商业：新的数字社会 <a class="header-anchor" href="#商业-新的数字社会" aria-label="Permalink to &quot;商业：新的数字社会&quot;">​</a></h2><blockquote><p>最终，每个人都会身处创作者经济之中。——纳瓦尔·拉维坎特 (Naval Ravikant)</p></blockquote><p>多亏了科技，世界正在从企业主导转向个人赋权。</p><p>这通过分裂与统一的原则反映在自然界中。</p><p>万物分离又重聚，就像海洋化为云朵再化为雨水，而创作者经济正是这种现象的完美例证。</p><p>在文艺复兴时期，经济偏爱多维型人才。博学者。那些拒绝限制自己能力的艺术家。那些思想家、创作者、设计师、建设者，以及为自身的精神、肉体和灵魂发展承担责任的个体。</p><p>在我们正在经历的数字文艺复兴中，历史正在重演。</p><p>拜指尖上庞大而快速扩张的信息所赐，我们可以学习任何东西，做任何事情，成为任何人。</p><p>精神存在层面（通过互联网）的扩张，创造了一个蕴含无限潜能的场域。</p><p>沟通不再局限于本地。</p><p>商业不再局限于本地。</p><p>友谊不再局限于本地。</p><p>社会不再碎片化。</p><p>创作者经济就是虚拟现实。</p><p>你的个人品牌就是你的角色。</p><p>线上生意就是这场游戏和你的进度。</p><p>人脉拓展是你建立强大部落的方式。</p><p>目标明确的产品是你谋生的手段。</p><p>你在整个旅程中培养的内在哲学，就是吸引同道中人的营销火力。</p><p>此刻，你就是创作者经济的一部分。</p><p>问题在于——你站在哪一边？</p><p>你是在参与价值交换的互惠互利吗？用产品换取金钱？还是在耗尽你的注意力、让大脑超载、浪费你的创造力，却不生产任何东西来回报你所攫取的价值？</p><p><img src="'+o+'" alt=""></p><h3 id="品牌——你是最赚钱的细分领域" tabindex="-1">品牌——你是最赚钱的细分领域 <a class="header-anchor" href="#品牌——你是最赚钱的细分领域" aria-label="Permalink to &quot;品牌——你是最赚钱的细分领域&quot;">​</a></h3><p>你的品牌就是你的线上化身。</p><p>强大的品牌拥有愿景。一个引领追随者向其迈进的、非理性的宏大目标。那个目标的引力——以及随之展现的能量——正是吸引人们走向你的原因。</p><p>你的品牌就是你最高阶的版本。</p><p>它是你正在成为的人。</p><p>它是指引你走向更美好未来的明灯，让你能够通过一个让他人也能获得巨大收益的有形载体，将你的行动与目标结合起来。</p><p>你的工作是在你的头像、图片、个人简介和网站中展示你是谁。</p><p>你的风格塑造你的设计。</p><p>你的愿景塑造你的简介。</p><p>你的目标塑造了你在品牌之下作为层级结构所创造的内容、产品和营销。</p><h3 id="内容——完成任务所学到的经验教训" tabindex="-1">内容——完成任务所学到的经验教训 <a class="header-anchor" href="#内容——完成任务所学到的经验教训" aria-label="Permalink to &quot;内容——完成任务所学到的经验教训&quot;">​</a></h3><p>你的内容就是你在追求极具挑战性的目标层级时，所获取的想法、思想、信念、观点、教训和建议。</p><p>你看到其中的威力了吗？</p><p>写作改变了我的生活。</p><p>它带来了自我觉察、自我理解，以及组织我思想的能力——或者说重整意识——让生活变得更加愉快。这就是我创建 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 的一个驱动因素——教给你这门可以说是有史以来最有价值（也是最赚钱）、并且永远不会过时的技能——哪怕人工智能已经出现。</p><p>你不需要花里胡哨的内容框架和模板。</p><p>当然，它们有帮助，但最好的内容源于能量传递。</p><p>当你通过教育和实践获得知识和技能时——分享那些激起你兴奋感与共鸣的想法。</p><p>不要过滤你自己。</p><p>这正是吸引志同道合读者的东西，它为你将毕生心血变现做好了准备。</p><h3 id="产品——用于行为改变的系统" tabindex="-1">产品——用于行为改变的系统 <a class="header-anchor" href="#产品——用于行为改变的系统" aria-label="Permalink to &quot;产品——用于行为改变的系统&quot;">​</a></h3><p>最好的产品能激发积极的行为改变。</p><p>行为改变反映在商业的永恒市场中——健康、财富和人际关系。</p><p>写给你自己。</p><p>为你自己构建。</p><p>卖给你自己。</p><p>用你在旅程中获得的知识和技能去创造一个产品或服务。</p><p>一个你曾经渴望拥有的东西，或者一个此刻能真正让你的生活受益的东西。</p><p>在创作者经济中，有人卖课程、服装、补剂、防蓝光眼镜、手帐本、多个人生领域的辅导、厨具，真的，任何能塑造像你这样的人的生活方式的东西都有人卖。</p><p>人们会反对，并告诉你去“做点正经生意”。</p><p>他们的意思是，“我在捏造对人类毫无益处的问题。不要围绕能够提升集体意识的真正问题去创业。”</p><p>那些与金钱关系糟糕的人认为销售和商业是邪恶的。</p><p>他们不明白商品交换是人类本性的一部分。</p><p>钱是中立的，直到它落入好人或坏人的手中。</p><p>朝着你清醒设定的目标持续迈进，能确保你倾向于善。</p><p>当你解决自己的问题并出售解决方案时，你可以确信这些问题在宏观宇宙尺度上同样存在，并可以安心入睡，因为你知道自己正在创造改变。</p><h3 id="营销——培养一种内在哲学" tabindex="-1">营销——培养一种内在哲学 <a class="header-anchor" href="#营销——培养一种内在哲学" aria-label="Permalink to &quot;营销——培养一种内在哲学&quot;">​</a></h3><p>学习营销和销售是明智的。</p><p>它们是有着价值交换的心理学和形而上学原则支撑的常青技能。</p><p>当然，这些技能也有被玷污的一面。缺乏道德发展的人会把它们用于作恶，但就像金钱一样，这些技能在被运用之前都是中立的。</p><p>投资相关的学习，但这样做的目的是为了注意其模式，并识别出那些塑造你表达和说服能力的原则。</p><p>在此基础上，运用你在玩这场游戏时培养出的内在哲学。</p><p>目标意味着问题，而问题意味着挣扎。</p><p>你在这个旅程中会挣扎，但你学到的经验教训正是提升你思想层级的东西。</p><p>你追求背后的<em>原因</em>或<em>“为什么”</em>，就是你向被你吸引的人推销你所创造产品的方式。</p><p>你为什么开始在健身房训练或者改善你的健康？</p><p>你为什么去改善你的人际关系和社交生活？</p><p>你为什么通过商业、技能和专业追求来增加你的财富？</p><p>这个“为什么”正是能在你的读者心中唤起情感的东西。</p><p>借由这些，你可以学习策略去在你的生意上进行测试以增加收入，但在这个过程中，不要失去你的灵魂。</p><p>朋友们，这期就到这里了。</p><p>生活是一场游戏。</p><p>——丹·柯 (Dan Koe)</p><hr><p><a href="/en/letters/life-is-a-video-game-you-cant-escape-the-matrix">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',226))])}const C=l(u,[["render",f]]);export{A as __pageData,C as default};
